module GitPullRequests
  # After Redmine has read a git repository's new commits (the post-receive
  # hook asks for that right after each push), close the pull requests whose
  # branch has been merged into their target.
  module RepositoryGitPatch
    def fetch_changesets
      super
    ensure
      GitPullRequests::RepositoryGitPatch.mark_merged(self)
    end

    def self.mark_merged(repository)
      status = IssueStatus.find_by(name: PullRequest::MERGED_STATUS)
      return unless status

      PullRequest.open_for(repository).each do |pr|
        sha = pr.merge_commit
        next unless sha

        changeset = repository.changesets.find_by(revision: sha)
        pr.issue.init_journal(changeset&.user || User.anonymous,
                              merged_note(repository, pr.target, sha))
        pr.issue.status = status
        if pr.issue.save
          # Redmine's own link from the issue to the merge commit ("Associated
          # revisions"): the Changes section is then computed from the merge
          # commit, so the branches can be deleted
          changeset.issues << pr.issue if changeset && !changeset.issues.include?(pr.issue)
        else
          Rails.logger.error("git_pull_requests: ##{pr.issue.id} not set to merged: " +
                             pr.issue.errors.full_messages.join(', '))
        end
      end
    rescue StandardError => e
      Rails.logger.error("git_pull_requests: #{e.class}: #{e.message}")
    end

    # "Merged into <target> in <project>:commit:<sha>" (a link in Redmine's
    # markup)
    def self.merged_note(repository, target, sha)
      repo = repository.identifier.present? ? "#{repository.identifier}|" : ''
      "Merged into #{target} in #{repository.project.identifier}:commit:#{repo}#{sha[0, 10]}"
    end
  end
end
